import {remotePicker} from '../components/remote-picker.js';
import {lookupOrders,reversePayment} from '../services/real-workshop.js';
import {sheetButton,bindSheetDownloads} from '../components/technical-sheet.js';
import {realMode} from '../services/api-service.js';
import {getStore,getContext,quoteTotal,balance,paidTotal,registerPayment,saveContact,confirmDelivery} from '../services/workshop-service.js';
import {e,money,date,stamp,field,select,checkbox,placeholder,selectOptions,link,button,submit,form,hint,pageHeader,bindForm,go,notify,showModal,table,badge} from '../components/ui.js';
import {icon} from '../components/icons.js';
import {permissionChecker} from '../services/permissions.js';
export function renderPayments({root,params,session}){
 const can=permissionChecker(session.role),canPay=can('pagos','registrar'),canDeliver=can('pagos','entregar');
 const s=getStore(),order=s.orders.find(o=>o.id===params.get('orden')),c=order?getContext(s,order):{},paid=order?paidTotal(s,order.id):0,pending=order?balance(s,order):0,delivery=order?.delivery;
 const contactOptions=()=>selectOptions(getStore().contacts.filter(x=>x.clientId===c.client?.id),x=>`${x.name} · ${x.documentType} ${x.documentNumber}`);
 root.innerHTML=pageHeader('Pago y entrega del vehículo','El pago y la identificación del receptor son acciones diferentes.')+
 form('1. PAGO DE LA ORDEN',select('Orden de trabajo','orderId',realMode?[placeholder()]:selectOptions(s.orders,o=>{const x=getContext(s,o);return `${o.code||o.id} / ${x.client?.name} / ${x.vehicle?.brand} ${x.vehicle?.model}`;}),order?.id||'','required')+
 `<div class="full-width payment-summary"><div><span>Total autorizado</span><strong>${money(order?pending+paid:0)}</strong></div><div><span>Pagado</span><strong>${money(paid)}</strong></div><div><span>Saldo pendiente</span><strong>${money(pending)}</strong></div>${order?badge(order.state):''}</div>`+
 field('Monto pagado','amount',order&&!delivery&&pending>0?(pending/100).toFixed(2):'','text','required inputmode="decimal" placeholder="450.00"')+select('Medio de pago','method',['Transferencia','Efectivo','Tarjeta']),submit('Registrar pago'),'payment-form')+
 form('2. ¿QUIÉN RETIRA EL VEHÍCULO?',`<p class="full-width form-description">Identifica a quien recoge el vehículo y comprueba su autorización para este retiro.</p><fieldset class="recipient-switch full-width"><legend class="sr-only">Persona que retira</legend>${['Propietario o titular','Persona autorizada','Representante de empresa'].map(kind=>`<label><input type="radio" name="kind" value="${e(kind)}" ${(delivery?.recipientKind||(delivery?.kind==='Tercero'?'Persona autorizada':'Propietario o titular'))===kind?'checked':''} ${delivery?'disabled':''}><span>${e(kind)}</span></label>`).join('')}</fieldset><div class="third-recipient full-width" ${delivery?.kind==='Tercero'?'':'hidden'}><div class="form-grid">${select('Contacto registrado vinculado al cliente','contactId',contactOptions(),delivery?.contactId||'',delivery?'disabled':'')}<div class="field-inline-link"><button type="button" class="secondary-button" id="new-contact" ${!order||delivery?'disabled':''}>+ Nuevo contacto</button></div></div></div>`+select('¿Cómo se verificó la autorización para este retiro?','method',[placeholder(),'Confirmación del titular','Documento','Representante facultado'],delivery?.method||'',delivery?'disabled':'required')+checkbox('Verifiqué identidad y autorización específica antes de entregar','verified',Boolean(delivery),delivery?'disabled':'')+checkbox('El receptor manifestó conformidad con la entrega y los trabajos realizados','conformity',Boolean(delivery?.conformity?.accepted),delivery?'disabled':'')+field('Observaciones de conformidad (opcional)','conformityNotes',delivery?.conformity?.notes||'','text',(delivery?'readonly':'')+' maxlength="1200"')+hint('La persona que trajo el vehículo no queda autorizada automáticamente para retirarlo.'),submit('Confirmar entrega'),'delivery-form');
 if(realMode)remotePicker(root.querySelector('[name=orderId]'),{selectedId:order?.id||'',initialLabel:order?[order.code,order.clientName,order.vehiclePlate].filter(Boolean).join(' · '):'',label:o=>[o.code,o.clientName,o.vehiclePlate].filter(Boolean).join(' · '),search:lookupOrders,onSelect:o=>go('pagos?orden='+o.id)});else root.querySelector('[name="orderId"]').onchange=ev=>go('pagos?orden='+ev.target.value);
 if(!order||pending<=0||delivery||!canPay)document.querySelector('#payment-form [type="submit"]').disabled=true;
 if(!order||delivery||!canDeliver)document.querySelector('#delivery-form [type="submit"]').disabled=true;
 if(!canPay||!canDeliver)root.insertAdjacentHTML('afterbegin',hint(`Tu rol no puede ${[!canPay&&'registrar pagos',!canDeliver&&'confirmar entregas'].filter(Boolean).join(' ni ')}.`));
 if(!canDeliver)document.getElementById('new-contact').disabled=true;
 root.querySelectorAll('[name="kind"]').forEach(radio=>radio.onchange=()=>root.querySelector('.third-recipient').hidden=radio.value==='Propietario o titular'||!radio.checked);
 let paymentRequestID=realMode?crypto.randomUUID():'';
 bindForm('payment-form',async data=>{const p=await registerPayment({...data,requestId:paymentRequestID},session.id);notify(`Pago ${p.id} registrado por ${money(p.amountCents)}.`);go('pagos?orden='+p.orderId);});
 bindForm('delivery-form',async data=>{await confirmDelivery({...data,orderId:order?.id},session.id);notify('Entrega confirmada y registrada.');go('pagos?orden='+order.id);});
 root.querySelector('#new-contact').onclick=()=>{
  const dialog=showModal('Nuevo contacto para retiro',hint('Esta persona se vincula al cliente seleccionado. Registrar el contacto no autoriza automáticamente la entrega.')+form('DATOS DEL CONTACTO',field('Nombre completo','name','','text','required maxlength="150"')+select('Tipo de documento','documentType',['DNI',{value:'CE',label:'Carné de extranjería'},'Pasaporte'])+field('N.º documento','documentNumber','','text','required maxlength="20"')+field('Teléfono internacional','phone','','tel','required maxlength="20" placeholder="+51987654321"')+select('Relación con el cliente','relation',['Conductor','Representante','Familiar','Otro']),submit('Guardar contacto')+button('Cancelar','cancel'),'contact-form'));
  dialog.querySelector('[data-action="cancel"]').onclick=()=>dialog.close();
  bindForm('contact-form',async data=>{const contact=await saveContact({...data,clientId:c.client.id});const sel=root.querySelector('[name="contactId"]');sel.innerHTML=contactOptions().map(o=>`<option value="${e(o.value)}" ${o.value===contact.id?'selected':''}>${e(o.label)}</option>`).join('');dialog.close();notify('Contacto registrado. Verifica la autorización para este retiro.');});
 };
 if(realMode&&order&&delivery&&pending===0)root.insertAdjacentHTML('beforeend',`<section class="panel separated"><h2 class="form-section-title">ATENCIÓN FINALIZADA</h2>${delivery.sheetReady===false?hint('La entrega está registrada. La ficha tiene contenido pendiente de generar; al descargar se indicará el motivo sin recortar información.') : ''}${sheetButton(order.id)}</section>`);
 bindSheetDownloads(root);
 if(order){root.insertAdjacentHTML('beforeend',`<section class="panel separated"><h2 class="form-section-title">PAGOS REGISTRADOS · ${e(order.id)}</h2>${table(['Pago','Fecha y hora','Monto','Medio','Registrado por','Rectificación'],s.payments.filter(p=>p.orderId===order.id).map(p=>[e(p.id),stamp(p.createdAt),money(p.amountCents),e(p.method),e(s.users.find(u=>u.id===p.createdBy)?.name||p.createdByName||p.createdBy),p.reversedAt?e('Revertido: '+(p.correction?.reason||'')):realMode&&can('pagos','rectificar')?`<button type="button" class="secondary-button" data-reverse="${e(p.id)}">${delivery?'Rectificar':'Revertir'}</button>`:'—']),'Todavía no hay pagos registrados.')}${delivery?`<div class="success-strip">${icon('check')}Vehículo entregado el ${stamp(delivery.at)}. Retiro: ${e(delivery.receiver?.name||delivery.name||(delivery.kind==='Tercero'?s.contacts.find(x=>x.id===delivery.contactId)?.name:c.client?.name))}. Verificado por ${e(s.users.find(u=>u.id===delivery.by)?.name)} mediante ${e(delivery.method)}.</div>`:''}</section>`);}
 root.querySelectorAll('[data-reverse]').forEach(b=>b.onclick=()=>{const key=crypto.randomUUID();const dialog=showModal('Revertir pago · '+b.dataset.reverse,form('RECTIFICACIÓN FINANCIERA',hint('Se conserva el pago original y se registra una reversión. Si corresponde, registra después el pago correcto.')+(delivery?hint('Atención entregada: se sustituirá el pago por otro del mismo importe, conservando ambos asientos.')+select('Medio de pago correcto','replacementMethod',['Transferencia','Efectivo','Tarjeta'])+field('Referencia del pago correcto (opcional)','replacementReceipt','','text','maxlength="50"'):'')+field('Motivo de la reversión','reason','','text','required minlength="5" maxlength="1200"'),submit('Confirmar reversión'),'reverse-form'));bindForm('reverse-form',async data=>{await reversePayment(order.id,b.dataset.reverse,data.reason,key,delivery?{method:data.replacementMethod,comprobante:data.replacementReceipt}:undefined);dialog.close();notify(delivery?'Pago rectificado sin alterar el saldo de la entrega.':'Pago revertido con trazabilidad.');go('pagos?orden='+order.id);});});

}
